#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_N 1000
#define MAX_M 100000

double dp[MAX_N + 1];
int out_deg[MAX_N + 1];
int to[MAX_N][MAX_M]; // adjacency list per node

int main() {
    int N, M;
    scanf("%d %d", &N, &M);

    for (int i = 1; i <= N; i++) {
        out_deg[i] = 0;
    }

    for (int i = 0; i < M; i++) {
        int s, t;
        scanf("%d %d", &s, &t);
        to[s][out_deg[s]++] = t;
    }

    // First compute dp without blocking
    dp[N] = 0.0;
    for (int u = N - 1; u >= 1; u--) {
        double sum = 0.0;
        for (int j = 0; j < out_deg[u]; j++) {
            int v = to[u][j];
            sum += dp[v];
        }
        dp[u] = 1.0 + sum / out_deg[u];
    }

    double original = dp[1];
    double best = original;

    // Try blocking one edge from each node
    for (int u = 1; u < N; u++) {
        if (out_deg[u] <= 1) continue; // blocking only edge forces dead end, not allowed by problem's guarantee but we skip anyway

        double sum = 0.0;
        for (int j = 0; j < out_deg[u]; j++) {
            int v = to[u][j];
            sum += dp[v];
        }

        // Try removing each outgoing edge
        for (int rem = 0; rem < out_deg[u]; rem++) {
            double new_sum = sum - dp[to[u][rem]];
            double new_dp_u = 1.0 + new_sum / (out_deg[u] - 1);

            // Recompute dp from 1 to u (only nodes before u are affected)
            double temp_dp[MAX_N + 1];
            memcpy(temp_dp, dp, sizeof(dp));
            temp_dp[u] = new_dp_u;

            for (int x = u - 1; x >= 1; x--) {
                double s2 = 0.0;
                for (int j = 0; j < out_deg[x]; j++) {
                    s2 += temp_dp[to[x][j]];
                }
                temp_dp[x] = 1.0 + s2 / out_deg[x];
            }

            if (temp_dp[1] > best) {
                best = temp_dp[1];
            }
        }
    }

    printf("%.10f\n", best);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int to, next;
} Edge;

static int cmp_int(const void *a, const void *b) {
    int x = *(const int*)a;
    int y = *(const int*)b;
    return (x > y) - (x < y);
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    int *head = (int*)malloc((N + 1) * sizeof(int));
    int *outdeg = (int*)calloc(N + 1, sizeof(int));
    Edge *edges = (Edge*)malloc(M * sizeof(Edge));

    for (int i = 1; i <= N; i++) head[i] = -1;

    int ecnt = 0;
    for (int i = 0; i < M; i++) {
        int s, t;
        scanf("%d %d", &s, &t);
        edges[ecnt].to = t;
        edges[ecnt].next = head[s];
        head[s] = ecnt++;
        outdeg[s]++;
    }

    /* dp0[v]: expected steps from v with no deletion */
    double *dp0 = (double*)calloc(N + 1, sizeof(double));
    for (int v = N - 1; v >= 1; v--) {
        double sum = 0.0;
        for (int e = head[v]; e != -1; e = edges[e].next) {
            sum += dp0[edges[e].to];
        }
        dp0[v] = 1.0 + sum / outdeg[v];
    }

    /* rev[u] = list of predecessors of u, to compute influence */
    int *rhead = (int*)malloc((N + 1) * sizeof(int));
    Edge *redges = (Edge*)malloc(M * sizeof(Edge));
    for (int i = 1; i <= N; i++) rhead[i] = -1;
    int recnt = 0;
    for (int v = 1; v <= N; v++) {
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int u = edges[e].to;
            redges[recnt].to = v;
            redges[recnt].next = rhead[u];
            rhead[u] = recnt++;
        }
    }

    /*
      prob[v]: expected number of visits to v starting from 1
      under the original process.
      Since graph is DAG with edges s<t, process in increasing order.
    */
    double *prob = (double*)calloc(N + 1, sizeof(double));
    prob[1] = 1.0;
    for (int v = 1; v <= N; v++) {
        if (v == N) continue;
        double p = prob[v] / outdeg[v];
        for (int e = head[v]; e != -1; e = edges[e].next) {
            prob[edges[e].to] += p;
        }
    }

    double ans = dp0[1];

    /*
      If we delete one outgoing edge from v (only possible if outdeg[v] >= 2),
      to minimize expectation from v we should delete the edge to the maximum dp0[to].
      New expectation at v:
        dp1[v] = 1 + (sum - maxdp) / (outdeg[v]-1)
      Total expectation from 1 changes by:
        prob[v] * (dp1[v] - dp0[v])
      because expected number of visits to v in this DAG process is prob[v].
    */
    for (int v = 1; v < N; v++) {
        if (outdeg[v] <= 1) continue;
        double sum = 0.0, mx = -1.0;
        for (int e = head[v]; e != -1; e = edges[e].next) {
            double x = dp0[edges[e].to];
            sum += x;
            if (x > mx) mx = x;
        }
        double dp1 = 1.0 + (sum - mx) / (outdeg[v] - 1);
        double cand = dp0[1] + prob[v] * (dp1 - dp0[v]);
        if (cand < ans) ans = cand;
    }

    printf("%.10f\n", ans);

    free(head);
    free(outdeg);
    free(edges);
    free(dp0);
    free(rhead);
    free(redges);
    free(prob);
    return 0;
}

