using namespace std;

int main() {
    int N, M;
    cin >> N >> M;
    vector<vector<int>> adj(N + 1);
    vector<pair<int,int>> edges(M);
    for (int i = 0; i < M; i++) {
        int s, t; cin >> s >> t;
        adj[s].push_back(t);
        edges[i] = {s, t};
    }

    auto compute = [&](int bs, int bt) -> double {
        vector<double> E(N + 1, 0);
        for (int i = N - 1; i >= 1; i--) {
            int deg = adj[i].size();
            double sum = 0;
            for (int j : adj[i]) {
                if (i == bs && j == bt) { deg--; continue; }
                sum += E[j];
            }
            if (deg == 0) { E[i] = 1e18; continue; }
            E[i] = 1.0 + sum / deg;
        }
        return E[1];
    };

    double ans = compute(-1, -1);
    for (auto [s, t] : edges) ans = min(ans, compute(s, t));

    cout << fixed << setprecision(9) << ans << endl;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<vector<int>> g(N + 1);
    vector<int> outdeg(N + 1, 0);

    for (int i = 0; i < M; ++i) {
        int s, t;
        cin >> s >> t;
        g[s].push_back(t);
        outdeg[s]++;
    }

    // dp0[i]: expected steps from i to N with no edge removed
    vector<double> dp0(N + 1, 0.0);
    dp0[N] = 0.0;
    for (int i = N - 1; i >= 1; --i) {
        double sum = 0.0;
        for (int to : g[i]) sum += dp0[to];
        dp0[i] = 1.0 + sum / outdeg[i];
    }

    // ans starts with "do nothing"
    double ans = dp0[1];

    // For each room v, consider removing one outgoing edge from v.
    // To minimize expectation at v, remove the edge to the child with maximum dp0[child].
    for (int v = 1; v <= N - 1; ++v) {
        if (outdeg[v] <= 1) continue; // removing would leave no outgoing edge, not allowed effectively

        double sumv = 0.0, mx = -1.0;
        for (int to : g[v]) {
            sumv += dp0[to];
            mx = max(mx, dp0[to]);
        }

        double newEv = 1.0 + (sumv - mx) / (outdeg[v] - 1);

        // dp1[i]: expected steps from i to N when one edge is removed at room v
        vector<double> dp1(N + 1, 0.0);
        dp1[N] = 0.0;
        for (int i = N - 1; i >= 1; --i) {
            if (i == v) {
                dp1[i] = newEv;
            } else {
                double sum = 0.0;
                for (int to : g[i]) sum += dp1[to];
                dp1[i] = 1.0 + sum / outdeg[i];
            }
        }

        ans = min(ans, dp1[1]);
    }

    cout << fixed << setprecision(10) << ans << '\n';
    return 0;
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();

        List<Integer>[] graph = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int i = 0; i < M; i++) {
            int s = sc.nextInt();
            int t = sc.nextInt();
            graph[s].add(t);
        }

        // dp[i] = expected number of passages from i to N
        double[] dp = new double[N + 1];
        dp[N] = 0.0;

        // Process rooms in reverse order
        for (int i = N - 1; i >= 1; i--) {
            if (graph[i].isEmpty()) continue;
            double sum = 0.0;
            for (int next : graph[i]) {
                sum += dp[next];
            }
            dp[i] = 1.0 + sum / graph[i].size();
        }

        double originalE = dp[1];
        double minE = originalE;

        // Try blocking each passage
        for (int i = 1; i <= N; i++) {
            if (graph[i].size() <= 1) continue; // blocking from a room with <=1 passage doesn't help or is invalid
            int k = graph[i].size();
            // We try to block each outgoing edge from i and recompute from i
            for (int blocked : graph[i]) {
                double sumWithoutBlocked = 0.0;
                for (int next : graph[i]) {
                    if (next != blocked) {
                        sumWithoutBlocked += dp[next];
                    }
                }
                // new expected value from i after blocking
                double newDpI = 1.0 + sumWithoutBlocked / (k - 1);
                // compute impact on dp[1] by propagating only through i
                // We can estimate by replacing dp[i] with newDpI in original expectation formula
                // but only if i is reachable from 1.
                double diff = newDpI - dp[i];
                // We need the probability of reaching i from 1.
                // Compute using linearity: we propagate from 1 to i.
                // Build probability of reaching each room from 1.
                double[] prob = new double[N + 1];
                prob[1] = 1.0;
                for (int u = 1; u < N; u++) {
                    if (graph[u].isEmpty()) continue;
                    double pOut = prob[u] / graph[u].size();
                    for (int v : graph[u]) {
                        prob[v] += pOut;
                    }
                }
                // Now the new expected value from 1 is originalE + diff * prob[i]
                double newE = originalE + diff * prob[i];
                if (newE < minE) {
                    minE = newE;
                }
            }
        }

        System.out.printf("%.10f\n", minE);
    }
}

