    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i <= N; i++) adj.add(new ArrayList<>());
        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            int s = Integer.parseInt(st.nextToken());
            int t = Integer.parseInt(st.nextToken());
            adj.get(s).add(t);
        }
        double[] E = new double[N + 1];
        E[N] = 0;
        for (int i = N - 1; i >= 1; i--) {
            List<Integer> neighbors = adj.get(i);
            int deg = neighbors.size();
            double sum = 0;
            for (int j : neighbors) sum += E[j];
            E[i] = 1 + sum / deg;
        }
        double[] reach = new double[N + 1];
        reach[1] = 1.0;
        for (int i = 1; i < N; i++) {
            List<Integer> neighbors = adj.get(i);
            int deg = neighbors.size();
            for (int j : neighbors) reach[j] += reach[i] / deg;
        }
        double best = E[1];
        for (int s = 1; s < N; s++) {
            List<Integer> neighbors = adj.get(s);
            int deg = neighbors.size();
            if (deg < 2) continue;
            double sum = 0;
            for (int j : neighbors) sum += E[j];
            // block passage (s, t) with max E[t]
            double maxE = -1;
            for (int j : neighbors) if (E[j] > maxE) maxE = E[j];
            double newEs = 1 + (sum - maxE) / (deg - 1);
            double delta = newEs - E[s];
            double newE1 = E[1] + delta * reach[s];
            if (newE1 < best) best = newE1;
        }
        System.out.println(best);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        int M = fs.nextInt();

        int[] outdeg = new int[N + 1];
        long[] sumTo = new long[N + 1];

        int[] s = new int[M];
        int[] t = new int[M];

        @SuppressWarnings("unchecked")
        ArrayList<Integer>[] adj = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) adj[i] = new ArrayList<>();

        for (int i = 0; i < M; i++) {
            int a = fs.nextInt();
            int b = fs.nextInt();
            s[i] = a;
            t[i] = b;
            outdeg[a]++;
            adj[a].add(b);
        }

        // dp[i]: expected steps from room i to N with no blocked edge
        double[] dp = new double[N + 1];
        dp[N] = 0.0;
        for (int i = N - 1; i >= 1; i--) {
            double sum = 0.0;
            for (int to : adj[i]) sum += dp[to];
            dp[i] = 1.0 + sum / outdeg[i];
        }

        // suffix probability of visiting each node from 1 under original process
        // p[i]: probability that Takahashi ever reaches room i
        double[] p = new double[N + 1];
        p[1] = 1.0;
        for (int i = 1; i <= N - 1; i++) {
            if (p[i] == 0.0) continue;
            double add = p[i] / outdeg[i];
            for (int to : adj[i]) p[to] += add;
        }

        double ans = dp[1]; // do nothing

        // Try blocking one outgoing edge from each room i
        // Best to remove edge to child with maximum dp[child]
        for (int i = 1; i <= N - 1; i++) {
            if (outdeg[i] <= 1) continue; // cannot improve / blocking would make no outgoing edge, invalid
            double sum = 0.0;
            double mx = -1.0;
            for (int to : adj[i]) {
                sum += dp[to];
                if (dp[to] > mx) mx = dp[to];
            }
            double original = 1.0 + sum / outdeg[i];
            double changed = 1.0 + (sum - mx) / (outdeg[i] - 1);
            double improvement = original - changed;
            double candidate = dp[1] - p[i] * improvement;
            if (candidate < ans) ans = candidate;
        }

        System.out.printf("%.10f%n", ans);
    }
}

import sys
from fractions import Fraction

def solve():
    input_data = sys.stdin.read().split()
    idx = 0
    N = int(input_data[idx]); idx+=1
    M = int(input_data[idx]); idx+=1

    edges = []
    adj = [[] for _ in range(N+1)]

    for _ in range(M):
        s = int(input_data[idx]); idx+=1
        t = int(input_data[idx]); idx+=1
        edges.append((s,t))
        adj[s].append(t)

    def compute_E(blocked=None):
        E = [Fraction(0)] * (N+1)
        for v in range(N-1, 0, -1):
            neighbors = [u for u in adj[v] if (v,u) != blocked]
            if not neighbors:
                E[v] = Fraction(10**18)  # unreachable/stuck
            else:
                k = len(neighbors)
                E[v] = Fraction(1) + sum(E[u] for u in neighbors) / k
        return E[1]

    best = compute_E()

    for (s,t) in edges:
        if len([u for u in adj[s]]) >= 2:
            val = compute_E(blocked=(s,t))
            if val < best:
                best = val

    # Print as fraction p/q or integer
    if best.denominator == 1:
        print(best.numerator)
    else:
        print(f"{best.numerator}/{best.denominator}")

solve()
